package org.apache.commons.math3.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.ConvergenceException;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ContinuedFraction.evaluate.
 * Since ContinuedFraction is abstract, we use a mock implementation to control getA and getB.
 */
public class ContinuedFraction_evaluate_TriageGen0Test {

    private static class TestContinuedFraction extends ContinuedFraction {
        private double aVal = 1.0;
        private double bVal = 1.0;
        private boolean triggerInfinity = false;
        private boolean triggerNaN = false;
        private boolean triggerScaleFailure = false;

        @Override
        protected double getA(int n, double x) {
            if (triggerInfinity && n > 0) return Double.POSITIVE_INFINITY;
            if (triggerNaN && n > 0) return Double.NaN;
            if (triggerScaleFailure) return -1.0; // To trigger scale <= 0
            return aVal;
        }

        @Override
        protected double getB(int n, double x) {
            if (triggerInfinity && n > 0) return Double.POSITIVE_INFINITY;
            if (triggerNaN && n > 0) return Double.NaN;
            return bVal;
        }

        public void setValues(double a, double b) {
            this.aVal = a;
            this.bVal = b;
        }

        public void setTriggerInfinity(boolean trigger) {
            this.triggerInfinity = trigger;
        }

        public void setTriggerNaN(boolean trigger) {
            this.triggerNaN = trigger;
        }

        public void setTriggerScaleFailure(boolean trigger) {
            this.triggerScaleFailure = trigger;
        }
    }

    @Test
    public void testEvaluate_Success() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // Simple case: a=1, b=1. Converges quickly.
        // deltaN = cN / q2 / cPrev. 
        // If cN/q2 is constant, deltaN - 1.0 will be 0 < epsilon.
        double result = cf.evaluate(1.0, 1e-10, 100);
        Assert.assertFalse(Double.isNaN(result));
    }

    @Test
    public void testEvaluate_SmallEpsilonZeroCheck() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // Force getA(0, x) to be 0 to trigger the 'small' epsilon check
        cf.setValues(0.0, 1.0);
        double result = cf.evaluate(1.0, 1e-10, 10);
        Assert.assertFalse(Double.isNaN(result));
    }

    @Test(expected = MaxCountExceededException.class)
    public void testEvaluate_MaxIterationsExceeded() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // Set values that prevent convergence (deltaN stays far from 1.0)
        cf.setValues(10.0, 0.1);
        cf.evaluate(1.0, 1e-20, 5);
    }

    @Test(expected = ConvergenceException.class)
    public void testEvaluate_InfinityDivergence() {
        TestContinuedFraction cf = new TestContinuedFraction();
        cf.setTriggerInfinity(true);
        cf.evaluate(1.0, 1e-10, 100);
    }

    @Test(expected = ConvergenceException.class)
    public void testEvaluate_NaN_Divergence() {
        TestContinuedFraction cf = new TestContinuedFraction();
        cf.setTriggerNaN(true);
        cf.evaluate(1.0, 1e-10, 100);
    }

    @Test(expected = ConvergenceException.class)
    public void testEvaluate_ScaleFactorFailure() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // Force infinity then trigger scale <= 0
        cf.setTriggerScaleFailure(true);
        cf.evaluate(1.0, 1e-10, 100);
    }

    @Test
    public void testEvaluate_ScalingBranch_A_Greater_Than_B() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // To hit the scaling logic, we need cN or q2 to be infinite, 
        // but the scaling loop should fix it.
        // We simulate this by making a and b very large.
        cf.setValues(1e300, 1e300); 
        // Note: The logic in the provided code is tricky to hit perfectly without 
        // precise control over the infinite state, but large values test the scale logic.
        double result = cf.evaluate(1.0, 1e-10, 10);
        Assert.assertFalse(Double.isNaN(result));
    }

    @Test
    public void testEvaluate_ScalingBranch_B_Not_Zero() {
        TestContinuedFraction cf = new TestContinuedFraction();
        // Testing the 'else if (b != 0)' branch in scaling
        // We need a < b to go into the second branch of the scaling logic
        cf.setValues(1.0, 1e300);
        // This might still trigger infinite check if not handled, 
        // but we are testing the branch coverage.
        try {
            cf.evaluate(1.0, 1e-10, 10);
        } catch (Exception e) {
            // Expected if it still fails to converge, but we want to ensure no crash
        }
    }

    @Test(expected = ConvergenceException.class)
    public void testEvaluate_InfiniteH_Divergence() {
        // This test targets the 'if (Double.isInfinite(hN))' check
        // We can achieve this by making a and b extremely large such that cN/q2 results in infinity
        TestContinuedFraction cf = new TestContinuedFraction();
        cf.setValues(Double.MAX_VALUE, Double.MAX_VALUE);
        // Note: The scaling logic might catch this first, so we test behavior.
        cf.evaluate(1.0, 1e-10, 100);
    }
}
